[ApiController]
[Route("api/v1/[controller]")]
[Authorize]
public class UsersController : ControllerBase
{
    private readonly IUserService _userService;
    private readonly ILogger<UsersController> _logger;

    public UsersController(IUserService userService, ILogger<UsersController> logger)
    {
        _userService = userService;
        _logger = logger;
    }

    [HttpGet("{id:int}")]
    [ProducesResponseType(typeof(UserDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<UserDto>> GetUser(int id, CancellationToken ct = default)
    {
        var user = await _userService.GetByIdAsync(id, ct);
        return user is null ? NotFound() : Ok(user);
    }

    [HttpPost]
    [ProducesResponseType(typeof(UserDto), StatusCodes.Status201Created)]
    public async Task<ActionResult<UserDto>> CreateUser(
        CreateUserDto dto, CancellationToken ct = default)
    {
        var user = await _userService.CreateAsync(dto, ct);
        return CreatedAtAction(nameof(GetUser), new { id = user.Id }, user);
    }
}

public class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> builder)
    {
        builder.ToTable("users");
        builder.HasKey(u => u.Id);
        builder.Property(u => u.Name).IsRequired().HasMaxLength(100);
        builder.Property(u => u.Email).IsRequired().HasMaxLength(255);
        builder.HasIndex(u => u.Email).IsUnique();
        builder.Property(u => u.CreatedAt).HasDefaultValueSql("CURRENT_TIMESTAMP");

        builder.HasMany(u => u.Roles)
            .WithMany(r => r.Users)
            .UsingEntity<Dictionary<string, object>>(
                "user_roles",
                j => j.HasOne<Role>().WithMany().HasForeignKey("RoleId"),
                j => j.HasOne<User>().WithMany().HasForeignKey("UserId")
            );

        // SetNull preserves orders when a user is soft-deleted.
        builder.HasMany(u => u.Orders)
            .WithOne(o => o.User)
            .HasForeignKey(o => o.UserId)
            .OnDelete(DeleteBehavior.SetNull);
    }
}

// Applied once in AppDbContext.OnModelCreating:
//   modelBuilder.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly);

public async Task<PagedResult<UserDto>> GetPageAsync(
    int page, int pageSize, CancellationToken ct)
{
    var q = _db.Users
        .AsNoTracking()
        .Include(u => u.Roles)
        .Include(u => u.Orders)
        .AsSplitQuery()
        .OrderBy(u => u.Id);

    var total = await q.CountAsync(ct);
    var items = await q.Skip((page - 1) * pageSize).Take(pageSize)
        .Select(u => new UserDto(u.Id, u.Name, u.Email))
        .ToListAsync(ct);

    return new PagedResult<UserDto>(items, total, page, pageSize);
}

public class BackgroundOrderProcessor : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<BackgroundOrderProcessor> _logger;
    private readonly Channel<int> _channel;

    public BackgroundOrderProcessor(
        IServiceScopeFactory scopeFactory,
        ILogger<BackgroundOrderProcessor> logger,
        Channel<int> channel)
    {
        _scopeFactory = scopeFactory;
        _logger = logger;
        _channel = channel;
    }

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        await foreach (var orderId in _channel.Reader.ReadAllAsync(ct))
        {
            try
            {
                using var scope = _scopeFactory.CreateScope();
                var svc = scope.ServiceProvider.GetRequiredService<IOrderService>();
                await svc.ProcessAsync(orderId, ct);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing order {OrderId}", orderId);
            }
        }
    }
}

