// Scheduled cleanup: PeriodicTimer, not Task.Delay in a loop.
protected override async Task ExecuteAsync(CancellationToken ct)
{
    using var timer = new PeriodicTimer(TimeSpan.FromMinutes(15));
    while (await timer.WaitForNextTickAsync(ct))
    {
        using var scope = _scopeFactory.CreateScope();
        await scope.ServiceProvider
            .GetRequiredService<ICleanupService>()
            .RunAsync(ct);
    }
}

public class UsersControllerTests
{
    private readonly Mock<IUserService> _mockService = new();
    private readonly UsersController _controller;

    public UsersControllerTests() =>
        _controller = new UsersController(
            _mockService.Object, Mock.Of<ILogger<UsersController>>());

    [Fact]
    public async Task GetUser_WhenExists_ReturnsOk()
    {
        var dto = new UserDto(1, "John", "j@example.com");
        _mockService.Setup(s => s.GetByIdAsync(1, It.IsAny<CancellationToken>()))
                    .ReturnsAsync(dto);

        var result = await _controller.GetUser(1);

        var ok = Assert.IsType<OkObjectResult>(result.Result);
        var returned = Assert.IsType<UserDto>(ok.Value);
        Assert.Equal(1, returned.Id);
    }

    [Fact]
    public async Task GetUser_WhenNotFound_ReturnsNotFound()
    {
        _mockService.Setup(s => s.GetByIdAsync(999, It.IsAny<CancellationToken>()))
                    .ReturnsAsync((UserDto?)null);
        var result = await _controller.GetUser(999);
        Assert.IsType<NotFoundResult>(result.Result);
    }
}

